getShopifyCustomer()
      .then((customer) => {
        if (!active) return;
        const tags = customer?.tags ?? [];
        setIsCreditAccount(
          tags.some((tag) =>
            ["credit account", "credit-account"].includes(tag.toLowerCase()),
          ),
        );
        setContactDetails(quoteContactDetailsFromCustomer(customer));
        setSignedInAccount(customer?.email ?? customer?.displayName ?? "");
      })
      .catch(() => {})
